(2498, 'Appointment creation email to patient', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>You have an appointment with <strong style=\"color:#0f172a;\">{doctorname}</strong> on <strong style=\"color:#0f172a;\">{appoinmentdate}</strong> at <strong style=\"color:#0f172a;\">{time_slot}</strong>. Please confirm your appointment.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'appoinment_creation', 'Active', '190'),
(2499, 'Meeting Schedule Notification To Patient', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{patient_name}</strong>,<br><br>You have a live video meeting with <strong style=\"color:#0f172a;\">{doctor_name}</strong> on <strong style=\"color:#0f172a;\">{start_time}</strong>.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'meeting_creation', 'Active', '190'),
(2500, 'Send Appointment confirmation to Doctor', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>You are registered to <strong style=\"color:#0f172a;\">{company}</strong> as a New Doctor in <strong style=\"color:#0f172a;\">{department}</strong>.\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef2ff; border:1px solid #c7d2fe; border-radius:10px; margin:20px 0;\">\r\n  <tr><td style=\"padding:16px 18px;\">\r\n    <div style=\"font-family:Arial,sans-serif; font-size:10px; font-weight:bold; letter-spacing:0.07em; text-transform:uppercase; color:#4f46e5; margin-bottom:10px;\">Login details</div>\r\n    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:13px;\">\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold; width:90px;\">Url</td><td style=\"padding:3px 0; color:#1e1b4b;\"><a href=\"https://{base_url}\" style=\"color:#4f46e5;\">{base_url}</a></td></tr>\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold;\">Username</td><td style=\"padding:3px 0; color:#1e1b4b; font-weight:bold;\">{email}</td></tr>\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold;\">Password</td><td style=\"padding:3px 0; color:#1e1b4b; font-weight:bold;\">{password}</td></tr>\r\n    </table>\r\n  </td></tr>\r\n</table>Thank you for registering.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'doctor', 'Active', '190'),
(2501, 'Patient Registration Confirmation', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>You are registered to <strong style=\"color:#0f172a;\">{company}</strong> as a New Patient to <strong style=\"color:#0f172a;\">{doctor}</strong>.\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef2ff; border:1px solid #c7d2fe; border-radius:10px; margin:20px 0;\">\r\n  <tr><td style=\"padding:16px 18px;\">\r\n    <div style=\"font-family:Arial,sans-serif; font-size:10px; font-weight:bold; letter-spacing:0.07em; text-transform:uppercase; color:#4f46e5; margin-bottom:10px;\">Login details</div>\r\n    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:13px;\">\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold; width:90px;\">Url</td><td style=\"padding:3px 0; color:#1e1b4b;\"><a href=\"https://{base_url}\" style=\"color:#4f46e5;\">{base_url}</a></td></tr>\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold;\">Username</td><td style=\"padding:3px 0; color:#1e1b4b; font-weight:bold;\">{email}</td></tr>\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold;\">Password</td><td style=\"padding:3px 0; color:#1e1b4b; font-weight:bold;\">{password}</td></tr>\r\n    </table>\r\n  </td></tr>\r\n</table>Thank you for registering.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'patient', 'Active', '190'),
