(3140, 'Doctor Appointment Update', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>Your appointment with <strong style=\"color:#0f172a;\">{patientname}</strong> on <strong style=\"color:#0f172a;\">{appoinmentdate}</strong> at <strong style=\"color:#0f172a;\">{time_slot}</strong> has been <strong style=\"color:#b45309;\">updated</strong>.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'doctor_appointment_update', 'Active', '227'),
(3141, 'Doctor Appointment Cancellation', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>Your appointment with <strong style=\"color:#0f172a;\">{patientname}</strong> on <strong style=\"color:#0f172a;\">{appoinmentdate}</strong> at <strong style=\"color:#0f172a;\">{time_slot}</strong> has been <strong style=\"color:#b91c1c;\">cancelled</strong>.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'doctor_appointment_cancel', 'Active', '227'),
(3142, 'Appointment Requested', 'Dear {firstname},<br> Your appointment with Dr. {doctorname} at {hospital_name} has been requested for {appoinmentdate} ({time_slot}). We will confirm shortly.<br><br> {hospital_name}<br>{hospital_phone}', 'appoinment_creation', 'Active', 'superadmin'),
(3143, 'Appointment Confirmed', 'Dear {firstname},<br> Your appointment with Dr. {doctorname} at {hospital_name} is confirmed for {appoinmentdate} ({time_slot}).<br><br> {hospital_name}<br>{hospital_phone}', 'appoinment_confirmation', 'Active', 'superadmin'),
(3144, 'New Appointment (Doctor notice)', 'Dear Dr. {lastname},<br> You have a new appointment with {patientname} on {appoinmentdate} ({time_slot}) at {hospital_name}.', 'appoinment_creation_to_doctor', 'Active', 'superadmin'),
(3145, 'Appointment Reminder', 'Dear {firstname},<br> This is a reminder of your appointment with Dr. {doctorname} today at {time_slot} ({hospital_name}).<br><br> {hospital_phone}', 'appoinment_remainder', 'Active', 'superadmin'),
(3146, 'Appointment Cancelled', 'Dear {firstname},<br> Your appointment with Dr. {doctorname} on {appoinmentdate} ({time_slot}) has been cancelled. Please contact {hospital_name} at {hospital_phone} to reschedule.', 'appointment_cancel', 'Active', 'superadmin'),
(3147, 'Appointment Cancelled (Doctor notice)', 'Dear Dr. {lastname},<br> The appointment with {patientname} on {appoinmentdate} ({time_slot}) has been cancelled.', 'doctor_appointment_cancel', 'Active', 'superadmin'),
(3148, 'Appointment Updated', 'Dear {firstname},<br> Your appointment with Dr. {doctorname} has been updated to {appoinmentdate} ({time_slot}) at {hospital_name}.', 'appointment_update', 'Active', 'superadmin'),
(3149, 'Appointment Updated (Doctor notice)', 'Dear Dr. {lastname},<br> The appointment with {patientname} has been updated to {appoinmentdate} ({time_slot}).', 'doctor_appointment_update', 'Active', 'superadmin'),
(3150, 'Payment Confirmation', 'Dear {firstname},<br> We have received your payment of {amount} at {hospital_name}. Thank you.<br><br> {hospital_name}<br>{hospital_phone}', 'payment', 'Active', 'superadmin'),
(3151, 'Meeting Scheduled', 'Dear {patient_name},<br> A video consultation with Dr. {doctor_name} has been scheduled for {start_time}.<br> Join link: {meeting_link}<br><br> {hospital_name}', 'meeting_creation', 'Active', 'superadmin'),
(3152, 'Lab Report Ready', 'Dear {name},<br> Your laboratory report {report_no} ({test_name}) is ready and attached as a PDF.<br> You can also view it online at {portal_url} using report number {report_no} and PIN {portal_pin}.<br><br> {hospital_name}', 'lab_report_ready', 'Active', 'superadmin'),
(3153, 'Pharmacy Sale Receipt', 'Dear {name},<br> Thank you for your purchase at {hospital_name} pharmacy. Invoice {invoice_no}, total {amount}, is attached as a PDF.<br><br> {hospital_name}', 'pharmacy_receipt', 'Active', 'superadmin'),
(3154, 'Medicine Low Stock Alert', 'Low stock alert at {hospital_name}: {medicine_name} has {current_stock} unit(s) left (reorder level {reorder_level}). Please reorder soon.', 'medicine_low_stock', 'Active', 'superadmin'),
(3155, 'Payment successful email to patient', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>Your payment of <strong style=\"color:#0f172a;\">Tk {amount}</strong> was successful. Thank you.<br><br>Please contact our support team for any queries.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'payment', 'Active', '228'),
(3156, 'Appointment Confirmation email to patient', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>Your appointment with <strong style=\"color:#0f172a;\">{doctorname}</strong> on <strong style=\"color:#0f172a;\">{appoinmentdate}</strong> at <strong style=\"color:#0f172a;\">{time_slot}</strong> is confirmed.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'appoinment_confirmation', 'Active', '228'),
(3157, 'Appointment creation email to patient', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>You have an appointment with <strong style=\"color:#0f172a;\">{doctorname}</strong> on <strong style=\"color:#0f172a;\">{appoinmentdate}</strong> at <strong style=\"color:#0f172a;\">{time_slot}</strong>. Please confirm your appointment.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'appoinment_creation', 'Active', '228'),
(3158, 'Meeting Schedule Notification To Patient', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{patient_name}</strong>,<br><br>You have a live video meeting with <strong style=\"color:#0f172a;\">{doctor_name}</strong> on <strong style=\"color:#0f172a;\">{start_time}</strong>.<br><br>For more information, contact <strong style=\"color:#0f172a;\">{hospital_name}</strong>.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'meeting_creation', 'Active', '228'),
(3159, 'Send Appointment confirmation to Doctor', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>You are registered to <strong style=\"color:#0f172a;\">{company}</strong> as a New Doctor in <strong style=\"color:#0f172a;\">{department}</strong>.\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef2ff; border:1px solid #c7d2fe; border-radius:10px; margin:20px 0;\">\r\n  <tr><td style=\"padding:16px 18px;\">\r\n    <div style=\"font-family:Arial,sans-serif; font-size:10px; font-weight:bold; letter-spacing:0.07em; text-transform:uppercase; color:#4f46e5; margin-bottom:10px;\">Login details</div>\r\n    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:13px;\">\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold; width:90px;\">Url</td><td style=\"padding:3px 0; color:#1e1b4b;\"><a href=\"https://{base_url}\" style=\"color:#4f46e5;\">{base_url}</a></td></tr>\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold;\">Username</td><td style=\"padding:3px 0; color:#1e1b4b; font-weight:bold;\">{email}</td></tr>\r\n      <tr><td style=\"padding:3px 0; color:#3730a3; font-weight:bold;\">Password</td><td style=\"padding:3px 0; color:#1e1b4b; font-weight:bold;\">{password}</td></tr>\r\n    </table>\r\n  </td></tr>\r\n</table>Thank you for registering.<br><br>Regards</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"background:#f8fafc; border-top:1px solid #e2e8f0; padding:18px 32px; text-align:center;\">\r\n          <div style=\"font-family:Arial,sans-serif; font-size:12px; color:#334155; font-weight:bold; margin-bottom:4px;\">{hospital_name}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#64748b; margin-bottom:10px;\">{hospital_phone} &nbsp;&middot;&nbsp; {hospital_email} &nbsp;&middot;&nbsp; {hospital_address}</div>\r\n          <div style=\"font-family:Arial,sans-serif; font-size:11px; color:#94a3b8;\">This is an automated message. Please do not reply directly to this email.</div>\r\n        </td>\r\n      </tr>\r\n    </table>\r\n  </td></tr>\r\n</table>', 'doctor', 'Active', '228'),
(3160, 'Patient Registration Confirmation', '\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f1f5f9; padding:24px 12px; font-family:Arial,Helvetica,sans-serif;\">\r\n  <tr><td align=\"center\">\r\n    <table role=\"presentation\" width=\"580\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:580px; width:100%; background:#ffffff; border-radius:14px; overflow:hidden; box-shadow:0 4px 16px rgba(15,23,42,0.08);\">\r\n      <tr>\r\n        <td style=\"background:#0f172a; padding:24px 32px; text-align:center;\">\r\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin:0 auto;\">\r\n            <tr><td style=\"width:44px; height:44px; background:#4f46e5; border-radius:10px; text-align:center; vertical-align:middle; font-size:20px; color:#ffffff; font-family:Arial,sans-serif;\">&#9993;</td></tr>\r\n          </table>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td style=\"padding:32px 36px;\">\r\n          <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:15px; line-height:1.8; color:#334155;\">\r\n            <tr><td>Dear <strong style=\"color:#0f172a;\">{name}</strong>,<br><br>You are registered to <strong style=\"color:#0f172a;\">{company}</strong> as a New Patient to <strong style=\"color:#0f172a;\">{doctor}</strong>.\r\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef2ff; border:1px solid #c7d2fe; border-radius:10px; margin:20px 0;\">\r\n  <tr><td style=\"padding:16px 18px;\">\r\n    <div style=\"font-family:Arial,sans-serif; font-size:10px; font-weight:bold; letter-spacing:0.07em; text-transform:uppercase; color:#4f46e5; margin-bottom:10px;\">Login details</div>\r\n    <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-family:Arial,sans-serif; font-size:13px;\">\r\n      <tr><td style=\"