INSERT INTO `template` (`id`, `name`, `template`, `user`, `x`, `hospital_id`, `category_id`) VALUES
(33, 'ertert', '<div style=\"max-width: 1000px; margin: 0 auto; font-family: Arial; font-size: 11px; border: 2px solid #000; background: #fff;\">\r\n<div style=\"background: linear-gradient(135deg,#4da6d4,#2c87b8); color: #fff; padding: 15px 20px;\">\r\n<table style=\"width: 100%; color: #fff;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 60px; font-size: 28px;\">⚕</td>\r\n<td><strong style=\"font-size: 20px;\">BALM OF GOD MEDICAL CENTER LTD.</strong><br><span style=\"font-size: 13px;\">(Diagnostic Research Laboratory Service Division)</span><br><span style=\"font-size: 10px;\">83 Nwaeke Street, off 104 Owerri Road, Aba | Tel: 0916 231 9889, 0705 200 1553</span></td>\r\n<td style=\"background: #fff; color: #2c87b8; padding: 10px; text-align: center; font-size: 12px; width: 180px;\"><strong>REQUEST/REPORTING FORM</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div style=\"background: #f0f0f0; padding: 10px 20px; border-bottom: 1px solid #000; font-size: 10px;\"><strong>DATE:</strong> <span style=\"border-bottom: 1px solid #666; display: inline-block; min-width: 100px;\" contenteditable=\"true\">________</span> &nbsp; <strong>PATIENT:</strong> <span style=\"border-bottom: 1px solid #666; display: inline-block; min-width: 200px;\" contenteditable=\"true\">______________</span> &nbsp; <strong>AGE:</strong> <span style=\"border-bottom: 1px solid #666; display: inline-block; min-width: 40px;\" contenteditable=\"true\">___</span> &nbsp; <strong>SEX:</strong> <span style=\"border-bottom: 1px solid #666; display: inline-block; min-width: 40px;\" contenteditable=\"true\">___</span><br><strong>DOCTOR:</strong> <span style=\"border-bottom: 1px solid #666; display: inline-block; min-width: 250px;\" contenteditable=\"true\">_________________</span> &nbsp; <strong>SPECIMEN:</strong> <span style=\"border-bottom: 1px solid #666; display: inline-block; min-width: 150px;\" contenteditable=\"true\">___________</span></div>\r\n<table style=\"width: 100%; border-collapse: collapse;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 50%; vertical-align: top; border-right: 1px solid #000; padding: 15px;\">\r\n<div style=\"background: #2c87b8; color: #fff; padding: 6px 10px; font-weight: bold; margin-bottom: 10px; font-size: 12px;\">CHEMISTRY</div>\r\n<table style=\"width: 100%; border-collapse: collapse; margin-bottom: 15px; font-size: 10px;\">\r\n<tbody>\r\n<tr style=\"background: #ddd;\">\r\n<th style=\"border: 1px solid #666; padding: 5px;\">TEST</th>\r\n<th style=\"border: 1px solid #666; padding: 5px;\">RESULT</th>\r\n<th style=\"border: 1px solid #666; padding: 5px;\">REFERENCE</th>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>FASTING BLOOD SUGAR</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">75-115mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>RANDOM</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">75-135mg/dl</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div style=\"background: #2c87b8; color: #fff; padding: 6px 10px; font-weight: bold; margin-bottom: 10px; font-size: 12px;\">LIVER FUNCTION TEST</div>\r\n<table style=\"width: 100%; border-collapse: collapse; margin-bottom: 15px; font-size: 10px;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>TOTAL BILIRUBIN</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">0.1-1.0mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>DIRECT BILIRUBIN</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">0.0-0.3</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>AST (SGOT)</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">0-20IU/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>ALT (SGPT)</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">0-20IU/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>ALK PHOSPHATASE</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">40-125u/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>TOTAL PROTEIN</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">60-82g/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>ALBUMIN</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">30-50g/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>GLOBULIN</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">10-35g/L</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div style=\"background: #2c87b8; color: #fff; padding: 6px 10px; font-weight: bold; margin-bottom: 10px; font-size: 12px;\">RENAL FUNCTION TEST</div>\r\n<table style=\"width: 100%; border-collapse: collapse; margin-bottom: 15px; font-size: 10px;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>SODIUM</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">135-150mmol/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>POTASSIUM</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">3.5-5.5mmol/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>CHLORIDE</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">95-110mmol/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>BICARBONATE</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">21-31mmol/L</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>CALCIUM</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">8.5-11mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>MAGNESIUM</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">1.7-2.1(MG/d)</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>PHOSPHORUS</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">2.5-4.5mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>URIC ACID</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">3.4-7.0mg/dl<br>2.5-6.5u, mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>CREATININE</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">0.6-2.0mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>UREA</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">10-50mg/dl</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div style=\"background: #2c87b8; color: #fff; padding: 6px 10px; font-weight: bold; margin-bottom: 10px; font-size: 12px;\">LIPID PROFILE</div>\r\n<table style=\"width: 100%; border-collapse: collapse; margin-bottom: 15px; font-size: 10px;\">\r\n<tbody>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>CHOLESTEROL</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">120-230mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>TRIGLYCERIDES</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">&lt;140mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>HDL</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style=\"border: 1px solid #666; padding: 5px;\">&gt;60mg/dl</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #666; padding: 5px;\"><strong>LDL</strong></td>\r\n<td style=\"border: 1px solid #666; padding: 5px; text-align: center;\"><span contenteditable=\"true\">___</span></td>\r\n<td style', '992', NULL, '98', '11'),
